import React from "react";
import { FaTrophy, FaProjectDiagram, FaCalendarAlt, FaPalette, FaBolt, FaUserGraduate, FaLeaf, FaMagic } from "react-icons/fa";

const Projects = () => {
  return (
    <section className="projects-page">

      {/* HERO */}
      <div className="hero">
        <h1>My Builds That Turn Ideas Into Reality</h1>
        <p>Full-stack creations, UI systems & real-world problem solving</p>
      </div>

      {/* FEATURED PROJECT - COHNI FLOW */}
      <div className="featured">
        <div className="featured-card">
          <div className="featured-icon"><FaMagic /></div>

          <div className="featured-content">
            <h2>Cohni Flow</h2>
            <p>
              An intelligent workflow-based system designed to simplify task flow
              and improve productivity through structured logic and automation.
              Built with a focus on clarity, efficiency, and user-driven design.
            </p>

            <div className="tech">React • UI Systems • Logic Design</div>

            <div className="buttons">
              <button>Live Demo</button>
              <button>GitHub</button>
            </div>
          </div>
        </div>
      </div>

      {/* PROJECTS GRID */}
      <div className="section">
        <h2>Other Projects</h2>

        <div className="projects-grid">

          <div className="project-card">
            <FaBolt className="icon" />
            <h3>EnergyPulse</h3>
            <p>
              AI-powered smart home dashboard with real-time biometric and energy visualization.
            </p>
            <span>React.js</span>
          </div>

          <div className="project-card">
            <FaUserGraduate className="icon" />
            <h3>Student Portal</h3>
            <p>
              Full-stack academic management system with secure backend and structured UI.
            </p>
            <span>Spring Boot • MySQL</span>
          </div>

          <div className="project-card">
            <FaLeaf className="icon" />
            <h3>Farm2Fork</h3>
            <p>
              Digital marketplace connecting farmers and consumers with smooth UI flow.
            </p>
            <span>HTML • CSS • JS</span>
          </div>

        </div>
      </div>

      {/* ACHIEVEMENTS TIMELINE */}
      <div className="section">
        <h2>Achievements</h2>

        <div className="timeline">

          <div className="item">
            <FaTrophy className="ticon" />
            <div>
              <h4>Hackathons</h4>
              <p>Semifinalist in Smart India Hackathon (SIH)</p>
            </div>
          </div>

          <div className="item">
            <FaProjectDiagram className="ticon" />
            <div>
              <h4>Best Project Award</h4>
              <p>Li-Fi innovation at International Conference</p>
            </div>
          </div>

          <div className="item">
            <FaCalendarAlt className="ticon" />
            <div>
              <h4>Tech Events</h4>
              <p>Organized Code Crunch coding challenge</p>
            </div>
          </div>

          <div className="item">
            <FaPalette className="ticon" />
            <div>
              <h4>Non-Tech Events</h4>
              <p>Managed team-based event coordination activities</p>
            </div>
          </div>

        </div>
      </div>

      {/* STYLE */}
      <style>{`

        .projects-page {
          min-height: 100vh;
          padding: 40px 10%;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
          font-family: "Poppins", sans-serif;
        }

        /* HERO */
        .hero {
          text-align: center;
          margin-bottom: 50px;
        }

        .hero h1 {
          font-size: 38px;
          color: #e2e8f0;
        }

        .hero p {
          color: #94a3b8;
          margin-top: 8px;
        }

        /* FEATURED */
        .featured {
          margin-bottom: 60px;
        }

        .featured-card {
          display: flex;
          gap: 20px;
          padding: 25px;
          border-radius: 18px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.3);
          box-shadow: 0 0 25px rgba(56,189,248,0.15);
        }

        .featured-icon {
          font-size: 34px;
          color: #38BDF8;
        }

        .featured-content h2 {
          color: #38BDF8;
          margin-bottom: 10px;
        }

        .featured-content p {
          color: #cbd5e1;
          line-height: 1.6;
        }

        .tech {
          margin-top: 10px;
          color: #94a3b8;
          font-size: 13px;
        }

        .buttons {
          margin-top: 15px;
          display: flex;
          gap: 10px;
        }

        .buttons button {
          padding: 8px 14px;
          border-radius: 8px;
          border: none;
          cursor: pointer;
          background: #38BDF8;
          color: #0b1220;
          font-weight: 600;
        }

        /* GRID */
        .section h2 {
          margin-bottom: 20px;
          color: #38BDF8;
        }

        .projects-grid {
          display: grid;
          grid-template-columns: repeat(3, 1fr);
          gap: 20px;
        }

        .project-card {
          padding: 20px;
          border-radius: 16px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.2);
          transition: 0.3s;
        }

        .project-card:hover {
          transform: translateY(-5px);
          border-color: #38BDF8;
        }

        .icon {
          color: #38BDF8;
          font-size: 22px;
          margin-bottom: 10px;
        }

        .project-card h3 {
          margin-bottom: 6px;
        }

        .project-card p {
          color: #cbd5e1;
          font-size: 14px;
        }

        .project-card span {
          display: inline-block;
          margin-top: 10px;
          color: #38BDF8;
          font-size: 12px;
        }

        /* TIMELINE */
        .timeline {
          display: flex;
          flex-direction: column;
          gap: 16px;
        }

        .item {
          display: flex;
          gap: 15px;
          padding: 14px;
          border-radius: 12px;
          background: rgba(255,255,255,0.03);
          border-left: 3px solid #38BDF8;
        }

        .ticon {
          color: #38BDF8;
          font-size: 20px;
        }

        .item h4 {
          margin: 0;
          color: #38BDF8;
        }

        .item p {
          margin: 4px 0 0;
          color: #cbd5e1;
          font-size: 14px;
        }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .projects-grid {
            grid-template-columns: 1fr;
          }

          .featured-card {
            flex-direction: column;
          }
        }

      `}</style>

    </section>
  );
};

export default Projects;
